struct Node { 
	int data; 
	struct Node* next; 
}; 

struct Node* reverseList(struct Node* head) 
{ 
	struct Node* prev = NULL; 
	struct Node* current = head; 
	struct Node* next; 
	while (current != NULL) { 
		next = current->next; 
		current->next = prev; 
		prev = current; 
		current = next; 
	} 
	head = prev; 
	return head; 
}

"""
Find the greatest common divisor for two integer inputs using the Euclidean Algorithm
"""

def greatest_common_divisor(int1, int2):
  if int1 == 0:
    return int2
  elif int2 == 0:
    return int1
  elif int1 == int2:
    return int1
  else:
    if int1 > int2:
      return greatest_common_divisor(int2, int1 % int2)
    else:
      return greatest_common_divisor(int1, int2 % int1)

