class Stack {
	private:
		int top = -1;
		int size;
		int *arr;

	public:
	    Stack(int n) {
	        size = n;
	        arr = new int[size];
	    }

	    void push(int x) {
	        if (top < size - 1) {
	            ++top;
	            arr[top] = x;
	        } else {
	            cout << "Stack overflow!" << endl;
	        }
	    }

	    int pop() {
	        if (top < 0) {
	            cout << "Stack underflow!" << endl;
	            return -1;
	        } else {
	            return arr[top--];
	        }
	    }

	    int topElement() {
	        if (top < 0) {
	            cout << "Stack underflow!" << endl;
	            return -1;
	        } else {
	            return arr[top];
	        }
	    }

	    int isEmpty() {
	        return top < 0;
	    }
};

function findLongestSubstring(s) {
  let longest = 0;
  let seen = {};
  let start = 0;

  for (let i = 0; i < s.length; i++) {
    let char = s[i];
    if (seen[char]) {
      start = Math.max(start, seen[char]);
    }
    // index - beginning of substring + 1 (to include current in count)
    longest = Math.max(longest, i - start + 1);
    // store the index of the next char so as to not double count
    seen[char] = i + 1;
  }
  return longest;
}

