    /* Returns an array of size 256 conaining count 
    of characters in the passed char array */
    static int[] getCharCountArray(String str) 
    { 
        int count[] = new int[NO_OF_CHARS]; 
        int len = str.length(); 

        /* Increment count of characters in count[] */
        for (int i = 0; i < len; i++) 
            count[str.charAt(i)]++; 

        return count; 
    } 

