def threeWayPartition(array, pivot): 
    less = [] 
    equal = [] 
    greater = [] 
    for i in array: 
        if i < pivot: 
            less.append(i) 
        elif i == pivot: 
            equal.append(i) 
        else: 
            greater.append(i)   
    return less + equal + greater 

