def transpose(matrix):
    m = len(matrix)
    n = len(matrix[0])

    transpose_matrix = [[0] * m for _ in range(n)]
    for i in range(m):
        for j in range(n):
            transpose_matrix[j][i] = matrix[i][j]

    return transpose_matrix

int binarySearch (int arr[], int l, int r, int x) 
{ 
    while ( l <= r) 
    { 
        int mid = l + (r-1)/2; 

        if (arr[mid] == x) 
            return mid; 

        if (arr[mid] < x) 
            l = mid + 1; 

        else
            r = mid - 1; 
    } 
    return -1; 
}

