  let nextNum = num + 1;
  while (isPrime) {
    for (let i = 2; i < nextNum; i++) {
      if (nextNum % i === 0) {
        nextNum++;
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      return nextNum;
    }
  }
