	{ 
		int result = 0, originalNumber, remainder; 

		originalNumber = number; 

		// Check if the number is Armstrong number 
		while (originalNumber != 0) { 
			remainder = originalNumber % 10; 
			result += Math.pow(remainder, 3); 
			originalNumber /= 10; 
		} 

		if (result == number) 
			return true; 
		else
			return false; 
	} 

